inventoryValidatorContract:
  { repositoryOnly = false } = {}
) {
  const events = repositoryOnly ? null : normalizeEvents(eventsDocument);
  const inventorySchemaVersions = new Set([
    "1.0-standalone-score-blind-inventory",
    "1.1-standalone-score-blind-inventory",
    "1.2-standalone-score-blind-inventory"
  ]);
  assertStandalone(
    inventorySchemaVersions.has(inventory?.schemaVersion) &&
      inventory.protocolId === STANDALONE_PROTOCOL_ID &&
      inventory.status === "complete-and-frozen" &&
      /^\d{2,}$/.test(inventory.debateNumber) &&
      semanticSectionIdPattern.test(inventory.debateId) &&
      inventory.assessmentModel === "5.6 Sol",
    "inventory: identity or status mismatch"
  );
  assertStandalone(
    Array.isArray(inventory.routes) && inventory.routes.length === 2,
    "inventory: exactly two routes required"
  );
  assertStandalone(
    canonicalJson(inventory.routes.map((route) => route.side).sort()) ===
      canonicalJson(["con", "pro"]),
    "inventory: one route per side required"
  );
  const bridgeIds = new Set();
  const speakerBySide = new Map();
  for (const route of inventory.routes) {
    assertStandalone(
      ["pro", "con"].includes(route.side) &&
        typeof route.speaker === "string" &&
        route.speaker.trim(),
      "inventory: each route requires a valid side and speaker"
    );
    speakerBySide.set(route.side, route.speaker);
    assertStandalone(
      Array.isArray(route.bridges) &&
        route.bridges.length >= 3 &&
        route.bridges.length <= 7,
      `${route.side}: bridge count outside 3..7`
    );
    const tiers = route.bridges.map((bridge) => bridge.tier);
    assertStandalone(
      tiers.filter((tier) => tier === "motion").length === 1 &&
        tiers.includes("central") &&
        tiers.includes("subsidiary"),
      `${route.side}: route must include motion, central, and subsidiary bridges`
    );
    for (const bridge of route.bridges) {
      assertString(bridge.bridgeId, `${route.side}.bridgeId`);
      assertStandalone(
        !bridgeIds.has(bridge.bridgeId),
        `inventory: duplicate bridge ${bridge.bridgeId}`
      );
      bridgeIds.add(bridge.bridgeId);
    }
  }

  assertStandalone(
    Array.isArray(inventory.sections) &&
      inventory.sections.length >= 4 &&
      inventory.sections.length <= 7,
    "inventory: section count outside 4..7"
  );
  const sectionIds = new Set();
  let weightTotal = 0;
  for (const section of inventory.sections) {
    assertString(section.sectionId, "section.sectionId");
    if (inventory.schemaVersion !== "1.0-standalone-score-blind-inventory") {
      assertStandalone(
        semanticSectionIdPattern.test(section.sectionId) &&
          !/^s\d+$/.test(section.sectionId),
        `${section.sectionId}: section ID must be a semantic lowercase slug`
      );
    }
    assertStandalone(
      !sectionIds.has(section.sectionId),
      `inventory: duplicate section ${section.sectionId}`
    );
    sectionIds.add(section.sectionId);
    assertStandalone(
      Number.isInteger(section.weightPercent) && section.weightPercent > 0,
      `${section.sectionId}: invalid weight`
    );
    weightTotal += section.weightPercent;
  }
  assertStandalone(weightTotal === 100, "inventory: section weights must total 100");

  assertStandalone(
    Array.isArray(inventory.moves) &&
      inventory.moves.length >= 8 &&
      inventory.moves.length <= 48,
    "inventory: move count outside 8..48"
  );
  const moveIds = allMoveIds(inventory);
  assertStandalone(
    moveIds.size === inventory.moves.length,
    "inventory: move IDs must be unique"
  );
  if (inventory.schemaVersion !== "1.0-standalone-score-blind-inventory") {
    assertStandalone(
      inventory.moves.every(
        (move) =>
          semanticSectionIdPattern.test(move.moveId) && !/^m\d+$/.test(move.moveId)
      ),
      "inventory: move IDs must be semantic lowercase slugs"
    );
  }
  let previousStartEvent = -1;
  for (const [index, move] of inventory.moves.entries()) {
    const label = `moves[${index}]`;
    assertStandalone(sectionIds.has(move.sectionId), `${label}: unknown section`);
    assertStandalone(
      ["pro", "con"].includes(move.side) &&
        move.speaker === speakerBySide.get(move.side),
      `${label}: speaker/side mismatch`
    );
    assertStandalone(
      ["constructive", "reply"].includes(move.moveKind),
      `${label}: invalid move kind`
    );
    const { startEvent, endEvent, startMs, endMs, excerpt } = move.sourceSpan ?? {};
    assertStandalone(
      Number.isInteger(startEvent) &&
        Number.isInteger(endEvent) &&
        startEvent >= 0 &&
        startEvent <= endEvent &&
        (repositoryOnly || endEvent < events.length),
      `${label}: invalid event span`
    );
    assertStandalone(
      startEvent >= previousStartEvent,
      `${label}: moves are not chronological`
    );
    previousStartEvent = startEvent;
    if (!repositoryOnly) {
      const expectedStart = events[startEvent].startMs;
      const expectedEnd =
        events[endEvent].startMs + events[endEvent].durationMs;
      assertStandalone(
        startMs === expectedStart && endMs === expectedEnd,
        `${label}: timestamp endpoints do not match events`
      );
      const expectedExcerpt = spanText(events, startEvent, endEvent);
      assertStandalone(excerpt === expectedExcerpt, `${label}: excerpt is not source-exact`);
    }
    assertStandalone(
      Array.isArray(move.quoteEligibleExactSpans),
      `${label}: quoteEligibleExactSpans must be an array`
    );
    for (const quote of move.quoteEligibleExactSpans) {
      assertStandalone(
        wordCount(quote) >= 3 &&
          wordCount(quote) <= 18 &&
          excerpt.includes(quote),
        `${label}: quote is not an exact 3-18 word source substring`
      );
    }
    assertStandalone(
      ["high", "medium", "low"].includes(move.attributionConfidence),
      `${label}: invalid attribution confidence`
    );
    assertStandalone(
      Number.isInteger(move.importance) && move.importance >= 1 && move.importance <= 3,
      `${label}: invalid importance`
    );
    assertStandalone(
      bridgeIds.has(move.burdenContact?.bridgeId),
      `${label}: unknown burden bridge`
    );
    assertStandalone(
      move.burdenContact.tier ===
        inventory.routes
          .flatMap((route) => route.bridges)
          .find((bridge) => bridge.bridgeId === move.burdenContact.bridgeId)?.tier,
      `${label}: burden tier differs from bridge`
    );
    assertStandalone(Array.isArray(move.respondsToIds), `${label}: respondsToIds missing`);
    assertStandalone(
      move.respondsToIds.every(
        (targetId) =>
          moveIds.has(targetId) &&
          inventory.moves.findIndex((candidate) => candidate.moveId === targetId) < index
      ),
      `${label}: response target must be an earlier move`
    );
    assertStandalone(
      Array.isArray(move.responseComponents),
      `${label}: responseComponents missing`
    );
    if (move.moveKind === "constructive") {
      assertStandalone(
        move.respondsToIds.length === 0 && move.responseComponents.length === 0,
        `${label}: constructive move cannot have response targets`
      );
    } else {
      assertStandalone(
        move.respondsToIds.length > 0 && move.responseComponents.length > 0,
        `${label}: reply requires response targets and components`
      );
      for (const component of move.responseComponents) {
        assertStandalone(
          move.respondsToIds.includes(component.targetMoveId),
          `${label}: response component target is not selected`
        );
      }
    }
  }
  for (const sectionId of sectionIds) {
    for (const side of ["pro", "con"]) {
      assertStandalone(
        inventory.moves.some(
          (move) => move.sectionId === sectionId && move.side === side
        ),
        `${sectionId}: ${side} has no move`
      );
    }
  }
  if (inventory.schemaVersion !== "1.0-standalone-score-blind-inventory") {
    const balance = inventory.selectionBalanceAudit;
    const actualTotals = Object.fromEntries(
      ["pro", "con"].map((side) => [
        side,
        inventory.moves.filter((move) => move.side === side).length
      ])
    );
    assertStandalone(
      balance?.thresholds?.totalAbsoluteDifference === 3 &&
        balance.thresholds.sectionAbsoluteDifference === 2 &&
        balance.totals?.pro === actualTotals.pro &&
        balance.totals?.con === actualTotals.con &&
        balance.totals?.absoluteDifference ===
          Math.abs(actualTotals.pro - actualTotals.con),
      "inventory: selectionBalanceAudit totals or thresholds differ"
    );
    assertStandalone(
      Array.isArray(balance.sections) &&
        balance.sections.length === inventory.sections.length,
      "inventory: selectionBalanceAudit sections differ"
    );
    const sectionDifferences = inventory.sections.map((section, index) => {
      const actual = Object.fromEntries(
        ["pro", "con"].map((side) => [
          side,
          inventory.moves.filter(
            (move) => move.sectionId === section.sectionId && move.side === side
          ).length
        ])
      );
      const stored = balance.sections[index];
      const difference = Math.abs(actual.pro - actual.con);
      assertStandalone(
        stored?.sectionId === section.sectionId &&
          stored.pro === actual.pro &&
          stored.con === actual.con &&
          stored.absoluteDifference === difference,
        `${section.sectionId}: selectionBalanceAudit count mismatch`
      );
      return difference;
    });
    const rationaleRequired =
      balance.totals.absoluteDifference >=
        balance.thresholds.totalAbsoluteDifference ||
      sectionDifferences.some(
        (difference) =>
          difference >= balance.thresholds.sectionAbsoluteDifference
      );
    assertStandalone(
      balance.rationaleRequired === rationaleRequired &&
        typeof balance.rationale === "string" &&
        (!rationaleRequired || balance.rationale.trim().length >= 40),
      "inventory: selectionBalanceAudit rationale requirement differs"
    );
  }
  if (inventory.schemaVersion === "1.2-standalone-score-blind-inventory") {
    const capacity = inventory.publicationCapacityAudit;
    assertStandalone(
      capacity?.maximumSelectedMovesPerSidePerSection === 4 &&
        Array.isArray(capacity.sections) &&
        capacity.sections.length === inventory.sections.length,
      "inventory: publicationCapacityAudit controls differ"
    );
    let allWithinCapacity = true;
    let allFourthRowsPreauthorized = true;
    for (const [index, section] of inventory.sections.entries()) {
      const counts = Object.fromEntries(
        ["pro", "con"].map((side) => [
          side,
          inventory.moves.filter(
            (move) => move.sectionId === section.sectionId && move.side === side
          ).length
        ])
      );
      const stored = capacity.sections[index];
      const fourthRowRequired = counts.pro === 4 || counts.con === 4;
      const withinCapacity = counts.pro <= 4 && counts.con <= 4;
      const fourthRowAuthorized =
        !fourthRowRequired ||
        (stored?.fourthRowAuthorized === true &&
          typeof stored?.rationale === "string" &&
          stored.rationale.trim().length >= 40);
      assertStandalone(
        stored?.sectionId === section.sectionId &&
          stored.pro === counts.pro &&
          stored.con === counts.con &&
          stored.withinCapacity === withinCapacity &&
          stored.fourthRowRequired === fourthRowRequired &&
          stored.fourthRowAuthorized === fourthRowAuthorized,
        `${section.sectionId}: publicationCapacityAudit differs from the locked inventory`
      );
      allWithinCapacity &&= withinCapacity;
      allFourthRowsPreauthorized &&= fourthRowAuthorized;
    }
    assertStandalone(
      capacity.allSectionsWithinCapacity === allWithinCapacity &&
        capacity.allFourthRowsPreauthorized === allFourthRowsPreauthorized &&
        allWithinCapacity &&
        allFourthRowsPreauthorized,
      "inventory: publication capacity or fourth-row authorization failed"
    );
  }
  assertStandalone(
    inventory.audit?.calculatedTotalsAbsent === true &&
      inventory.audit?.completeTranscriptReviewed === true &&
      inventory.audit?.allSpansSourceExact === true,
    "inventory: required audit claims missing"
  );
  return {
    status: "passed",
    debateNumber: inventory.debateNumber,
    sections: inventory.sections.length,
    moves: inventory.moves.length,
    belowHighAttributionMoveIds: inventory.moves
      .filter((move) => move.attributionConfidence !== "high")
      .map((move) => move.moveId)
  };
}

export function validatePrimarySpeakerScopeException({
  authorization,
  sourceLock,
  inventory
}) {
  const authorizationScope = authorization?.identity?.primarySpeakerScopeException;
  const sourceScope = sourceLock?.participants?.primarySpeakerScopeException;
  const audit = inventory?.primarySpeakerScopeAudit;
  assertStandalone(
    authorizationScope?.enabled === true &&
      authorizationScope.protocolId === PRIMARY_SPEAKER_SCOPE_PROTOCOL_ID &&
      sourceScope?.enabled === true &&
      sourceScope.protocolId === PRIMARY_SPEAKER_SCOPE_PROTOCOL_ID &&
      audit?.protocolId === PRIMARY_SPEAKER_SCOPE_PROTOCOL_ID &&
      audit.status === "complete-and-frozen-before-judgment",
    "primary-speaker scope: identity or status mismatch"
  );
  assertStandalone(
    canonicalJson(authorizationScope.primarySpeakers) ===
        canonicalJson(sourceScope.primarySpeakers) &&
      canonicalJson(authorizationScope.primarySpeakers) ===
        canonicalJson(audit.primarySpeakers) &&
      canonicalJson(authorizationScope.nonPrimarySpeakers) ===
        canonicalJson(sourceScope.nonPrimarySpeakers) &&
      canonicalJson(authorizationScope.nonPrimarySpeakers) ===
        canonicalJson(audit.nonPrimarySpeakers) &&
      canonicalJson(authorizationScope.maximumHostAdvocacyShare) ===
        canonicalJson(sourceScope.maximumHostAdvocacyShare) &&
      canonicalJson(authorizationScope.maximumHostAdvocacyShare) ===
        canonicalJson(audit.maximumHostAdvocacyShare),
    "primary-speaker scope: participant identities or threshold differ"
  );
  assertStandalone(
    audit.primarySpeakers?.pro === authorization?.identity?.pro?.speaker &&
      audit.primarySpeakers?.con === authorization?.identity?.con?.speaker &&
      audit.primarySpeakers?.pro === sourceLock?.participants?.pro &&
      audit.primarySpeakers?.con === sourceLock?.participants?.con &&
      audit.primarySpeakers.pro !== audit.primarySpeakers.con &&
      Array.isArray(audit.nonPrimarySpeakers) &&
      audit.nonPrimarySpeakers.length > 0,
    "primary-speaker scope: primary speakers do not match the frozen debate identity"
  );
  const nonPrimaryNames = new Set();
  for (const [index, participant] of audit.nonPrimarySpeakers.entries()) {
    assertStandalone(
      typeof participant?.name === "string" &&
        participant.name.trim() &&
        typeof participant?.role === "string" &&
        participant.role.trim() &&
        !nonPrimaryNames.has(participant.name) &&
        !Object.values(audit.primarySpeakers).includes(participant.name),
      `primary-speaker scope: invalid non-primary participant ${index}`
    );
    nonPrimaryNames.add(participant.name);
  }
  assertStandalone(
    canonicalJson(authorizationScope.assessedWindow) ===
        canonicalJson(sourceScope.assessedWindow) &&
      canonicalJson(authorizationScope.assessedWindow) ===
        canonicalJson(audit.assessedWindow) &&
      canonicalJson(authorizationScope.excludedIntervals) ===
        canonicalJson(sourceScope.excludedIntervals) &&
      canonicalJson(authorizationScope.excludedIntervals) ===
        canonicalJson(audit.excludedIntervals),
    "primary-speaker scope: authorization, source, and inventory boundaries differ"
  );
  const window = audit.assessedWindow;
  assertStandalone(
    Number.isInteger(window?.startMs) &&
      Number.isInteger(window?.endMs) &&
      Number.isInteger(window?.durationMs) &&
      window.startMs >= 0 &&
      window.endMs > window.startMs &&
      window.durationMs === window.endMs - window.startMs,
    "primary-speaker scope: invalid assessed window"
  );
  assertStandalone(
    audit.maximumHostAdvocacyShare === 0.05 &&
      Array.isArray(audit.excludedIntervals) &&
      audit.excludedIntervals.length > 0,
    "primary-speaker scope: missing 5% control or exclusions"
  );
  const intervalIds = new Set();
  let hostDurationMs = 0;
  let dependentResponseDurationMs = 0;
  const intervals = [...audit.excludedIntervals].sort(
    (left, right) => left.startMs - right.startMs
  );
  for (const [index, interval] of intervals.entries()) {
    assertStandalone(
      typeof interval.intervalId === "string" &&
        interval.intervalId.trim() &&
        !intervalIds.has(interval.intervalId) &&
        ["host-advocacy", "dependent-response"].includes(interval.kind) &&
        typeof interval.speaker === "string" &&
        interval.speaker.trim() &&
        Number.isInteger(interval.startMs) &&
        Number.isInteger(interval.endMs) &&
        Number.isInteger(interval.durationMs) &&
        interval.startMs >= window.startMs &&
        interval.endMs <= window.endMs &&
        interval.endMs > interval.startMs &&
        interval.durationMs === interval.endMs - interval.startMs &&
        typeof interval.summary === "string" &&
        interval.summary.trim().length >= 40 &&
        typeof interval.burdenImpactRationale === "string" &&
        interval.burdenImpactRationale.trim().length >= 40 &&
        interval.uniqueLoadBearingArgument === false,
      `primary-speaker scope: invalid excluded interval ${index}`
    );
    intervalIds.add(interval.intervalId);
    if (interval.kind === "host-advocacy") {
      assertStandalone(
        nonPrimaryNames.has(interval.speaker),
        `primary-speaker scope: ${interval.intervalId} is not attributed to a frozen non-primary participant`
      );
      hostDurationMs += interval.durationMs;
    } else {
      assertStandalone(
        Object.values(audit.primarySpeakers).includes(interval.speaker),
        `primary-speaker scope: ${interval.intervalId} is not attributed to a primary speaker`
      );
      dependentResponseDurationMs += interval.durationMs;
    }
  }
  const mergedIntervals = [];
  for (const interval of intervals) {
    const previous = mergedIntervals.at(-1);
    if (!previous || interval.startMs > previous.endMs) {
      mergedIntervals.push({ startMs: interval.startMs, endMs: interval.endMs });
    } else {
      previous.endMs = Math.max(previous.endMs, interval.endMs);
    }
  }
  const totalExcludedDurationMs = mergedIntervals.reduce(
    (sum, interval) => sum + interval.endMs - interval.startMs,
    0
  );
  const hostAdvocacyShare = hostDurationMs / window.durationMs;
  assertStandalone(
    audit.derivedDurations?.hostAdvocacyMs === hostDurationMs &&
      audit.derivedDurations?.dependentResponseMs === dependentResponseDurationMs &&
      audit.derivedDurations?.totalExcludedMs === totalExcludedDurationMs &&
      Math.abs(audit.derivedDurations.hostAdvocacyShare - hostAdvocacyShare) < 1e-12 &&
      hostAdvocacyShare <= audit.maximumHostAdvocacyShare,
    "primary-speaker scope: duration totals or 5% threshold differ"
  );
  assertStandalone(
    audit.allHostInterventionsEnumerated === true &&
      audit.noDistinctSideIntroduced === true &&
      audit.noUniqueLoadBearingArgumentIntroduced === true &&
      audit.noSelectedEvidenceIntersectsExclusions === true &&
      audit.neitherSideCreditedOrPenalized === true &&
      audit.readerDisclosureRequired === true,
    "primary-speaker scope: required audit conclusions missing"
  );
  const overlaps = [];
  assertStandalone(
    Array.isArray(inventory.moves),
    "primary-speaker scope: inventory moves are missing"
  );
  for (const move of inventory.moves) {
    for (const interval of intervals) {
      if (move.sourceSpan.startMs < interval.endMs && move.sourceSpan.endMs > interval.startMs) {
        overlaps.push(`${move.moveId}:${interval.intervalId}`);
      }
    }
  }
  assertStandalone(
    overlaps.length === 0,
    `primary-speaker scope: selected evidence intersects exclusions: ${overlaps.join(", ")}`
  );
  return {
    status: "passed",
    protocolId: PRIMARY_SPEAKER_SCOPE_PROTOCOL_ID,
    hostAdvocacyMs: hostDurationMs,
    dependentResponseMs: dependentResponseDurationMs,
    hostAdvocacyShare
  };
}
